def format_id_with_check_digit(n, width):
    padded = str(n).zfill(width)
    check = sum(int(d) for d in padded if d.isdigit()) % 10
    return padded + str(check)

def format_id_grouped(n, width, group):
    padded = str(n).zfill(width)
    chunks = [padded[i:i + group] for i in range(0, len(padded), group)]
    return "-".join(chunks)

def parse_and_reformat_id(id_str, new_width):
    stripped = id_str.lstrip("0")
    if stripped == "":
        stripped = "0"
    return stripped.zfill(new_width)

def sentence_case(s):
    lowered = s.lower()
    for i, ch in enumerate(lowered):
        if ch.isalpha():
            return lowered[:i] + ch.upper() + lowered[i + 1:]
    return lowered

def sentence_case_multi(text):
    parts = text.split(". ")
    result = []
    for part in parts:
        lowered = part.lower()
        fixed = lowered
        for i, ch in enumerate(lowered):
            if ch.isalpha():
                fixed = lowered[:i] + ch.upper() + lowered[i + 1:]
                break
        result.append(fixed)
    return ". ".join(result)

def capitalize_first_word_each_line(text):
    lines = text.split("\n")
    out = []
    for line in lines:
        if line == "":
            out.append(line)
            continue
        lowered = line.lower()
        fixed = lowered
        for i, ch in enumerate(lowered):
            if ch.isalpha():
                fixed = lowered[:i] + ch.upper() + lowered[i + 1:]
                break
        out.append(fixed)
    return "\n".join(out)

def sentence_case_preserve_acronyms(s, acronyms):
    lowered = s.lower()
    for i, ch in enumerate(lowered):
        if ch.isalpha():
            lowered = lowered[:i] + ch.upper() + lowered[i + 1:]
            break
    words = lowered.split(" ")
    acro_map = {a.lower(): a for a in acronyms}
    fixed_words = [acro_map.get(w.lower(), w) for w in words]
    return " ".join(fixed_words)

def fix_sentence_spacing(s):
    collapsed = " ".join(s.split())
    lowered = collapsed.lower()
    for i, ch in enumerate(lowered):
        if ch.isalpha():
            return lowered[:i] + ch.upper() + lowered[i + 1:]
    return lowered

def capitalize_after_colon(s):
    lowered = s.lower()
    chars = list(lowered)

    def cap_at(idx):
        for i in range(idx, len(chars)):
            if chars[i].isalpha():
                chars[i] = chars[i].upper()
                return

    cap_at(0)
    idx = lowered.find(": ")
    while idx != -1:
        cap_at(idx + 2)
        idx = lowered.find(": ", idx + 1)
    return "".join(chars)

def sentence_case_keep_i(s):
    lowered = s.lower()
    words = lowered.split(" ")
    words = ["I" if w == "i" else w for w in words]
    joined = " ".join(words)
    for i, ch in enumerate(joined):
        if ch.isalpha():
            return joined[:i] + ch.upper() + joined[i + 1:]
    return joined

def toggle_sentence_case(s):
    lowered = s.lower()
    idx = None
    for i, ch in enumerate(lowered):
        if ch.isalpha():
            idx = i
            break
    if idx is None:
        return lowered
    chars = list(lowered)
    for i in range(len(chars)):
        if chars[i].isalpha() and i != idx:
            chars[i] = chars[i].upper()
    return "".join(chars)

def sanitize_filename_basic(name):
    allowed = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.")
    return "".join(c if c in allowed else "_" for c in name)

def sanitize_filename_spaces(name):
    replaced = name.replace(" ", "_")
    allowed = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-")
    return "".join(c for c in replaced if c in allowed)

def sanitize_filename_lower(name):
    lowered = name.lower().replace(" ", "-")
    allowed = set("abcdefghijklmnopqrstuvwxyz0123456789-.")
    return "".join(c for c in lowered if c in allowed)

def truncate_filename(name, max_len):
    if len(name) <= max_len:
        return name
    if "." in name:
        base, ext = name.rsplit(".", 1)
        ext = "." + ext
        keep = max_len - len(ext)
        if keep < 0:
            return name[:max_len]
        return base[:keep] + ext
    return name[:max_len]
